<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {memberRpc,memberApi} from './member-service.js'
const rows=ref([]),selected=ref(null),search=ref(''),page=ref(0),hasNext=ref(false),busy=ref(false),message=ref(''),password=ref(''),confirmWithdraw=ref(false),requestId=ref(crypto.randomUUID())
let epoch=0
async function run(fn){if(busy.value)return;busy.value=true;message.value='';try{await fn()}catch(e){message.value=e.message}finally{busy.value=false;password.value=''}}
async function load(){const id=++epoch;const data=await memberRpc('member_admin_list',{p_search:search.value,p_offset:page.value*50});if(id!==epoch)return;hasNext.value=data.length>50;rows.value=data.slice(0,50)}
function choose(row){selected.value=row?{...row}:{id:null,email:'',display_name:'',company:'',member_kind:'business',status:'active'};password.value='';confirmWithdraw.value=false;requestId.value=crypto.randomUUID()}
async function save(){await run(async()=>{const s=selected.value;await memberApi({action:s.id?'update':'create',request_id:requestId.value,user_id:s.id,email:s.email,name:s.display_name,company:s.company,kind:s.member_kind,...(!s.id?{password:password.value}:{})});await load();message.value=s.id?'회원정보를 저장했습니다.':'회원을 등록했습니다. 회원에게 자동 메일은 발송하지 않습니다.';selected.value=null;requestId.value=crypto.randomUUID()})}
async function setPassword(){await run(async()=>{await memberApi({action:'password',request_id:crypto.randomUUID(),user_id:selected.value.id,password:password.value});message.value='PMOffice 비밀번호를 변경했습니다. 회원에게 자동 메일은 발송하지 않습니다.'})}
async function withdraw(){if(!confirmWithdraw.value)return;await run(async()=>{const result=await memberApi({action:'withdraw',request_id:crypto.randomUUID(),user_id:selected.value.id});await load();selected.value=null;message.value=result.warning||'탈퇴 처리했습니다. 기존 세션의 자료 접근도 차단됩니다.'})}
onMounted(()=>run(load));onUnmounted(()=>{++epoch;rows.value=[];selected.value=null;password.value=''})
</script>
<template><main class="member-page"><h1>회원 관리</h1><p role="status" aria-live="polite">{{message}}</p><div class="member-actions"><button @click="choose(null)">회원 직접 등록</button></div><div class="member-columns"><section class="member-panel"><form @submit.prevent="page=0;run(load)" class="member-form"><label>회원 검색<input v-model="search" maxlength="200" placeholder="이메일, 이름, 회사명"></label><button :disabled="busy">검색·새로고침</button></form><div class="member-list"><button class="member-row" :class="{selected:selected?.id===r.id}" v-for="r in rows" :key="r.id" @click="choose(r)"><strong>{{r.display_name||'이름 미입력'}}</strong><span>{{r.email}}</span><span>{{r.company||'개인'}} · {{r.withdrawn_at?'탈퇴':r.status==='active'?'이용 중':'중지'}}</span></button></div><div class="member-actions"><button :disabled="busy||page===0" @click="page--;run(load)">이전</button><span>{{page+1}}</span><button :disabled="busy||!hasNext" @click="page++;run(load)">다음</button></div></section>
<section v-if="selected" class="member-panel"><h2>{{selected.id?'회원정보 수정':'회원 직접 등록'}}</h2><form @submit.prevent="save" class="member-form"><label>회원 구분<select v-model="selected.member_kind"><option value="business">기업·기관 회원</option><option value="individual">개인 회원</option></select></label><label>이름<input v-model="selected.display_name" required maxlength="120"></label><label>회사명·소속{{selected.member_kind==='individual'?' (선택)':''}}<input v-model="selected.company" :required="selected.member_kind==='business'" maxlength="200"></label><label>이메일<input v-model="selected.email" type="email" required maxlength="254"></label><label v-if="!selected.id">초기 비밀번호<input v-model="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><p v-if="!selected.id" class="member-note">지정하신 비밀번호로 바로 로그인할 수 있습니다. 첫 로그인 비밀번호 변경 안내나 자동 이메일은 보내지 않습니다.</p><button :disabled="busy">{{selected.id?'회원정보 저장':'회원 등록'}}</button></form>
<template v-if="selected.id"><h3>가입 기록</h3><p>가입 경로: {{selected.registration_source}} · 등록 시각: {{selected.registered_at||selected.created_at}}</p><p>회원 본인 가입 동의: {{selected.signup_accepted_at||'기록 없음 (관리자 등록과 구분)'}}</p><h3>소속 그룹</h3><ul><li v-for="g in selected.groups" :key="g.id">{{g.name}} · {{g.active?'포함':'중지 또는 제외'}}</li></ul><h3>PMOffice 비밀번호 변경</h3><form @submit.prevent="setPassword" class="member-form"><label>새 비밀번호<input v-model="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><button :disabled="busy">비밀번호 변경</button></form><h3>회원 탈퇴 처리</h3><p>회원정보와 처리 이력을 보존하고 사이트 이용을 중지합니다.</p><label class="member-check"><input v-model="confirmWithdraw" type="checkbox"><span>{{selected.display_name||selected.email}} 회원의 이용 중지 확인</span></label><button :disabled="busy||!confirmWithdraw||!!selected.withdrawn_at" @click="withdraw">탈퇴 처리</button></template></section><section v-else class="member-panel"><p>회원을 선택하거나 새 회원을 등록해 주세요.</p></section></div></main></template>
